package com.dutchvocabulary.controller;

import com.dutchvocabulary.dto.AuthResponse;
import com.dutchvocabulary.dto.LoginRequest;
import com.dutchvocabulary.dto.RegisterRequest;
import com.dutchvocabulary.model.User;
import com.dutchvocabulary.repository.UserRepository;
import com.dutchvocabulary.security.JwtUtils;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.BadCredentialsException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;

import java.time.LocalDateTime;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
@CrossOrigin(origins = "*")
public class AuthController {

    private final AuthenticationManager authenticationManager;
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtils jwtUtils;

    @PostMapping("/register")
    public ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest request) {
        // Check if username already exists
        if (userRepository.existsByUsername(request.getUsername())) {
            return ResponseEntity.badRequest()
                    .body(AuthResponse.builder()
                            .message("Username already exists")
                            .build());
        }

        // Create new user
        User user = User.builder()
                .username(request.getUsername())
                .password(passwordEncoder.encode(request.getPassword()))
                .displayName(request.getDisplayName() != null ? request.getDisplayName() : request.getUsername())
                .createdAt(LocalDateTime.now())
                .build();

        userRepository.save(user);

        // Generate token
        String token = jwtUtils.generateToken(user.getUsername());

        return ResponseEntity.status(HttpStatus.CREATED)
                .body(AuthResponse.builder()
                        .token(token)
                        .username(user.getUsername())
                        .displayName(user.getDisplayName())
                        .message("Registration successful")
                        .build());
    }

    @PostMapping("/login")
    public ResponseEntity<AuthResponse> login(@Valid @RequestBody LoginRequest request) {
        try {
            Authentication authentication = authenticationManager.authenticate(
                    new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword())
            );

            SecurityContextHolder.getContext().setAuthentication(authentication);

            // Update last login
            User user = userRepository.findByUsername(request.getUsername())
                    .orElseThrow();
            user.setLastLoginAt(LocalDateTime.now());
            userRepository.save(user);

            // Generate token
            String token = jwtUtils.generateToken(user.getUsername());

            return ResponseEntity.ok(AuthResponse.builder()
                    .token(token)
                    .username(user.getUsername())
                    .displayName(user.getDisplayName())
                    .message("Login successful")
                    .build());

        } catch (BadCredentialsException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(AuthResponse.builder()
                            .message("Invalid username or password")
                            .build());
        }
    }

    @GetMapping("/me")
    public ResponseEntity<AuthResponse> getCurrentUser() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();

        if (authentication == null || !authentication.isAuthenticated() || 
            "anonymousUser".equals(authentication.getPrincipal())) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(AuthResponse.builder()
                            .message("Not authenticated")
                            .build());
        }

        String username = authentication.getName();
        User user = userRepository.findByUsername(username)
                .orElse(null);

        if (user == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(AuthResponse.builder()
                            .message("User not found")
                            .build());
        }

        return ResponseEntity.ok(AuthResponse.builder()
                .username(user.getUsername())
                .displayName(user.getDisplayName())
                .build());
    }
}

package com.dutchvocabulary.controller;

import com.dutchvocabulary.dto.*;
import com.dutchvocabulary.service.QuizService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/quiz")
@RequiredArgsConstructor
@CrossOrigin(origins = "*")
public class QuizController {

    private final QuizService quizService;

    /**
     * Generate a random quiz.
     * @param count Number of questions (default: 10)
     * @param category Optional category filter
     * @param difficulty Optional difficulty filter (EASY, MEDIUM, HARD)
     */
    @GetMapping
    public ResponseEntity<List<QuizQuestionDTO>> generateQuiz(
            @RequestParam(defaultValue = "10") int count,
            @RequestParam(required = false) String category,
            @RequestParam(required = false) String difficulty) {
        return ResponseEntity.ok(quizService.generateQuiz(count, category, difficulty));
    }

    /**
     * Generate a smart quiz focusing on weak words and spaced repetition.
     * @param count Number of questions (default: 10)
     */
    @GetMapping("/smart")
    public ResponseEntity<List<QuizQuestionDTO>> generateSmartQuiz(
            @RequestParam(defaultValue = "10") int count) {
        return ResponseEntity.ok(quizService.generateSmartQuiz(count));
    }

    /**
     * Submit an answer to a single question.
     */
    @PostMapping("/answer")
    public ResponseEntity<QuizResultDTO> submitAnswer(@Valid @RequestBody QuizAnswerDTO answerDTO) {
        return ResponseEntity.ok(quizService.submitAnswer(answerDTO));
    }

    /**
     * Submit answers for an entire quiz.
     */
    @PostMapping("/submit")
    public ResponseEntity<List<QuizResultDTO>> submitQuiz(@Valid @RequestBody List<QuizAnswerDTO> answers) {
        return ResponseEntity.ok(quizService.submitQuiz(answers));
    }

    /**
     * Get learning statistics.
     */
    @GetMapping("/statistics")
    public ResponseEntity<StatisticsDTO> getStatistics() {
        return ResponseEntity.ok(quizService.getStatistics());
    }
}

package com.dutchvocabulary.controller;

import com.dutchvocabulary.dto.VocabularyWordDTO;
import com.dutchvocabulary.model.Difficulty;
import com.dutchvocabulary.model.VocabularyWord;
import com.dutchvocabulary.service.VocabularyService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/words")
@RequiredArgsConstructor
@CrossOrigin(origins = "*")
public class VocabularyController {

    private final VocabularyService vocabularyService;

    /**
     * Get all vocabulary words.
     */
    @GetMapping
    public ResponseEntity<List<VocabularyWord>> getAllWords() {
        return ResponseEntity.ok(vocabularyService.getAllWords());
    }

    /**
     * Get a word by ID.
     */
    @GetMapping("/{id}")
    public ResponseEntity<VocabularyWord> getWordById(@PathVariable Long id) {
        return vocabularyService.getWordById(id)
                .map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    /**
     * Get words by category.
     */
    @GetMapping("/category/{category}")
    public ResponseEntity<List<VocabularyWord>> getWordsByCategory(@PathVariable String category) {
        return ResponseEntity.ok(vocabularyService.getWordsByCategory(category));
    }

    /**
     * Get words by difficulty.
     */
    @GetMapping("/difficulty/{difficulty}")
    public ResponseEntity<List<VocabularyWord>> getWordsByDifficulty(@PathVariable String difficulty) {
        try {
            Difficulty diff = Difficulty.valueOf(difficulty.toUpperCase());
            return ResponseEntity.ok(vocabularyService.getWordsByDifficulty(diff));
        } catch (IllegalArgumentException e) {
            return ResponseEntity.badRequest().build();
        }
    }

    /**
     * Get all available categories.
     */
    @GetMapping("/categories")
    public ResponseEntity<List<String>> getAllCategories() {
        return ResponseEntity.ok(vocabularyService.getAllCategories());
    }

    /**
     * Search words by Dutch or English term.
     */
    @GetMapping("/search")
    public ResponseEntity<List<VocabularyWord>> searchWords(@RequestParam String q) {
        return ResponseEntity.ok(vocabularyService.searchWords(q));
    }

    /**
     * Create a new vocabulary word.
     */
    @PostMapping
    public ResponseEntity<VocabularyWord> createWord(@Valid @RequestBody VocabularyWordDTO dto) {
        VocabularyWord created = vocabularyService.createWord(dto);
        return ResponseEntity.status(HttpStatus.CREATED).body(created);
    }

    /**
     * Update an existing word.
     */
    @PutMapping("/{id}")
    public ResponseEntity<VocabularyWord> updateWord(
            @PathVariable Long id,
            @Valid @RequestBody VocabularyWordDTO dto) {
        return vocabularyService.updateWord(id, dto)
                .map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    /**
     * Delete a word.
     */
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteWord(@PathVariable Long id) {
        if (vocabularyService.deleteWord(id)) {
            return ResponseEntity.noContent().build();
        }
        return ResponseEntity.notFound().build();
    }
}

